class BakiyeYetersiz(Exception):
    pass

try:
    raise BakiyeYetersiz("bakiye 0")
except BakiyeYetersiz as e:
    print("hata:", e)

class UygulamaHatasi(Exception):
    pass

class AgHatasi(UygulamaHatasi):
    pass

try:
    raise AgHatasi("bağlantı yok")
except UygulamaHatasi:
    print("yakalandı")

class AyarHatasi(Exception):
    pass

try:
    try:
        int("x")
    except ValueError as e:
        raise AyarHatasi("ayar okunamadı") from e
except AyarHatasi as h:
    print(h, "| sebep:", type(h.__cause__).__name__)
